const paragraph = (t: Topic, angle: string, index: number) => `In ${t.title.toLowerCase()}, ${angle} is a concrete operating question rather than a decorative field. The Filipino caller starts with the approved record, states what is known, and asks only what the workflow permits. If the answer is absent or contradictory, the caller keeps that uncertainty visible. The note should preserve the contact’s words, the source used, and the next action that the named owner can actually take. This protects the customer from an invented promise and protects the team from a result label that cannot be explained later. The ${t.owner} decides policy, eligibility, commercial terms, or any change beyond the released routine. A disciplined handoff therefore includes the record reference, conversation result, unresolved point, and requested decision. ` +
  (index % 2 ? `A useful review asks whether another person could understand the state without replaying the entire call. It checks accuracy, respectful tone, minimum necessary information, and a clear stop point. Volume can be reported separately, but it cannot substitute for a complete disposition. ` : `For a practical day, write the check before the queue opens, use it during the conversation, and revisit it at close. That simple rhythm turns a vague activity into evidence about list quality, script fit, and ownership. `);

export const aug19SourceRepair3BlogPosts = topics.map((t) => ({ slug: t.slug, title: t.title, excerpt: t.excerpt, minutes: 14, published: repairPublicationDates[t.slug] }));

export function makeAug19SourceRepair3Detail(post: typeof aug19SourceRepair3BlogPosts[number]) {
  const t = topics.find((x) => x.slug === post.slug)!;
  const sections = t.angles.map((angle, i) => ({ heading: `${angle[0].toUpperCase()}${angle.slice(1)} for ${t.title.toLowerCase()}`, paragraphs: [paragraph(t, angle, i), paragraph(t, `${angle} at the handoff`, i + 1)] }));
  return {
    published: repairPublicationDates[t.slug], mainKeyword: t.title, metaLabel: 'Philippines staffing blog',
    directAnswerHeading: `How to manage ${t.title.toLowerCase()}`,
    body: t.sourceBody,
    summary: `${t.title} gives a Filipino caller a bounded way to answer one operational question: ${t.question} The record remains useful because ${t.owner} receives evidence instead of an unsupported conclusion.`,
    takeaways: [`Start with the question: ${t.question}`, 'Separate observed evidence from an owner decision.', 'Use the smallest approved set of record details.', 'Keep uncertainty and stop conditions visible.', `Route the unresolved decision to ${t.owner}.`],
    decisionTable: [{lane:'Purpose',caller:'Uses the released brief and explains the immediate question.',owner:'Defines the purpose, audience, and approved outcome.',measure:'The call has a named reason'}, {lane:'Evidence',caller:'Records the answer, refusal, uncertainty, and source.',owner:'Decides whether the evidence is sufficient.',measure:'The note can be checked'}, {lane:'Boundary',caller:'Pauses at a sensitive or unsupported request.',owner:`Owns the decision as ${t.owner}.`,measure:'No guess becomes a promise'}, {lane:'Handoff',caller:'Sends result, open point, and requested action.',owner:'Reviews the exception and updates the workflow.',measure:'The next action has an owner'}],
    planningBands: [{label:'Question',value:'One',note:t.question},{label:'Evidence',value:'Named',note:'Record source and answer'},{label:'Boundary',value:'Visible',note:'Pause before guessing'},{label:'Owner',value:'Clear',note:t.owner}],
    sections, scripts: [{title:'Opening',text:`I am calling about ${t.title.toLowerCase()}. I will keep this focused on the approved question.`},{title:'Clarifying',text:'I want to record that accurately. May I confirm the point you just described?'},{title:'Boundary',text:`I can record that request, but ${t.owner} needs to decide the next step.`}],
    workflow: [{step:'1',title:'Prepare',text:'Check the queue, source, purpose, and release rules.'},{step:'2',title:'Ask',text:'Use neutral wording and capture the answer.'},{step:'3',title:'Label',text:'Choose a truthful result and preserve uncertainty.'},{step:'4',title:'Route',text:`Send the open decision to ${t.owner}.`},{step:'5',title:'Review',text:'Compare the note with the resulting system state.'}],
    faqs: [{q:`What makes ${t.title.toLowerCase()} useful?`,a:`It links one clear question to evidence, an unresolved point, and the owner responsible for the next decision.`},{q:'What if the record does not support the next step?',a:'Pause, record what is missing, and route the exception. Do not fill a required field with an assumption.'},{q:'What should the manager review?',a:'Review a sample for source fidelity, complete dispositions, respectful handling, and whether the caller stopped at the approved boundary.'}],
    related: [{label:'Appointment setting service',href:'/services/appointment-setting'},{label:'Customer follow-up service',href:'/services/customer-follow-up-calls'},{label:'Call quality review service',href:'/services/call-quality-review'}],
    sources: [{name:'FCC Telephone Consumer Protection Act guidance',url:'https://www.fcc.gov/general/telemarketing-and-telephone-consumer-protection-act'},{name:'FTC business guidance on data security',url:'https://www.ftc.gov/business-guidance/privacy-security/data-security'},{name:'NIST Privacy Framework',url:'https://www.nist.gov/privacy-framework'}]
  };
}
